1	//! GLM5.2 MLA front half: the q_a/kv_a/q_b projections and norms from
2	//! `hidden[T, 6144]` into the persistent front scratch, plus the layer's
3	//! device-resident attention weights. The attend half (absorb, FlashMLA
4	//! sparse decode, o_proj) lives in `mla_decode` and consumes the front's
5	//! buffers.
6	
7	use anyhow::Result;
8	use anyhow::ensure;
9	use cudarc::driver::CudaSlice;
10	use half::bf16;
11	use pegainfer_kernels::ops::GLM52_GEMV_MMA_SCRATCH_FLOATS_PER_ROW;
12	use pegainfer_kernels::ops::extract_hidden_rows_raw_into;
13	use pegainfer_kernels::ops::glm52_gemv_mma_routes;
14	use pegainfer_kernels::ops::glm52_gemv_split_reduce_launch;
15	use pegainfer_kernels::ops::glm52_mla_ckv_split_launch;
16	use pegainfer_kernels::ops::rms_norm_rows_into;
17	use pegainfer_kernels::tensor::DeviceContext;
18	use pegainfer_kernels::tensor::DeviceVec;
19	
20	use crate::config::GLM52_HEADS;
21	use crate::config::GLM52_HIDDEN;
22	use crate::config::GLM52_KV_A_OUT;
23	use crate::config::GLM52_KV_LORA_RANK;
