43	// Local short names for the config-owned architecture constants (the module
44	// is dense with shape math; the values live in one place).
45	const HEADS: usize = GLM52_HEADS;
46	const HIDDEN: usize = GLM52_HIDDEN;
47	const Q_LORA: usize = GLM52_Q_LORA_RANK;
48	const QK_NOPE: usize = GLM52_QK_NOPE_HEAD_DIM; // absorbed q nope width per head
49	const Q_HEAD: usize = GLM52_QK_HEAD_DIM; // qk_nope(192) + qk_rope(64)
50	const ROPE_DIM: usize = GLM52_QK_ROPE_HEAD_DIM;
51	const KV_LORA: usize = GLM52_KV_LORA_RANK;
52	const KV_A_OUT: usize = GLM52_KV_A_OUT; // compressed_kv(512) + k_pe(64)
53	const V_HEAD: usize = GLM52_V_HEAD_DIM;
54	const KV_B_ROWS_PER_HEAD: usize = QK_NOPE + V_HEAD; // 448
