56	/// One MLA layer's attention weights, device-resident. `heads` is the number
57	/// of q/v heads THIS instance carries: the full 64, or an attention-TP head
58	/// shard (8 of 64 per rank) — q_b/kv_b/o_proj arrive pre-sliced and every
59	/// head-indexed shape below follows `heads`. The FlashMLA query/latent stay
60	/// full-width regardless (see `Glm52MlaAttendScratch`).
61	pub(crate) struct Glm52MlaLayerWeights {
62	    q_a: ProjWeight,
63	    q_a_ln: DeviceVec,
64	    q_b: ProjWeight,
65	    kv_a: ProjWeight,
66	    pub(crate) kv_a_ln: DeviceVec,
67	    pub(crate) o_proj: ProjWeight,
68	    pub(crate) w_uk: CudaSlice<bf16>, // [heads, 192, 512]
69	    pub(crate) w_uv: CudaSlice<bf16>, // [heads, 256, 512]
70	    // Horizontal q_a|kv_a pack ([2624, 6144]): both projections read `hidden`,
71	    // and one batched mma launch over the packed weight costs the same as q_a
72	    // alone (7.3 vs 7.1 us at batch 8 on GB300 — the kv_a bytes ride free).
73	    // Built only where the mma table routes the packed shape (Blackwell batch
74	    // 8); everywhere else the separate weights above stay the launch path, so
75	    // the twin costs ~15.4 MiB/layer only where it earns its keep. The
76	    // wide-bucket GEMM route (#812) reuses the same pack: one GEMM + one
77	    // activation quant replace the separate q_a/kv_a pair there too.
78	    qa_kva: Option<ProjWeight>,
79	    pub(crate) heads: usize,
80	}
