82	impl Glm52MlaLayerWeights {
83	    /// Build from raw checkpoint bytes: upload the fp8 projections + bf16
84	    /// layernorm gammas, and host-dequant kv_b into the bf16 absorb factors
85	    /// W_UK = kv_b[:, :192, :], W_UV = kv_b[:, 192:, :].
86	    #[cfg(test)]
87	    pub(crate) fn from_host(
88	        ctx: &DeviceContext,
89	        q_a: &Glm52ProjBytes,
90	        q_a_ln: &[u8],
91	        q_b: &Glm52ProjBytes,
92	        kv_a: &Glm52ProjBytes,
93	        kv_a_ln: &[u8],
94	        kv_b: &Glm52ProjBytes,
95	        o_proj: &Glm52ProjBytes,
96	    ) -> Result<Self> {
97	        // Pin every projection to the MLA architecture at load time: a checkpoint
98	        // with the wrong shape would otherwise sail through the self-consistent
99	        // `upload` len check and only die deep in the forward (a GPU slice panic).
100	        let check = |label: &str, p: &Glm52ProjBytes, n: usize, k: usize| -> Result<()> {
101	            ensure!(
102	                p.n == n && p.k == k,
103	                "GLM5.2 {label} shape [{},{}] != [{n},{k}]",
104	                p.n,
105	                p.k
106	            );
107	            Ok(())
108	        };
109	        let heads = mla_heads(q_b.n, kv_b.n, o_proj.k)?;
110	        check("q_a_proj", q_a, Q_LORA, HIDDEN)?;
111	        check("q_b_proj", q_b, heads * Q_HEAD, Q_LORA)?;
112	        check("kv_a_proj_with_mqa", kv_a, KV_A_OUT, HIDDEN)?;
113	        check("kv_b_proj", kv_b, heads * KV_B_ROWS_PER_HEAD, KV_LORA)?;
114	        check("o_proj", o_proj, HIDDEN, heads * V_HEAD)?;
115	        let (w_uk, w_uv) = dequant_kv_b(ctx, kv_b)?;
116	        let q_a = ProjWeight::upload(ctx, q_a)?;
117	        let kv_a = ProjWeight::upload(ctx, kv_a)?;
118	        let qa_kva = pack_qa_kva(ctx, &q_a, &kv_a)?;
119	        Ok(Self {
120	            q_a,
121	            q_a_ln: DeviceVec::from_safetensors(ctx, q_a_ln)?,
122	            q_b: ProjWeight::upload(ctx, q_b)?,
123	            kv_a,
124	            kv_a_ln: DeviceVec::from_safetensors(ctx, kv_a_ln)?,
125	            o_proj: ProjWeight::upload(ctx, o_proj)?,
126	            w_uk,
127	            w_uv,
128	            qa_kva,
129	            heads,
130	        })
131	    }
132	
133	    /// Build from already-resident weights (the production loader path). The fp8
134	    /// projections + layernorm gammas are moved in; `kv_b` is consumed to derive
135	    /// the bf16 absorb factors (its fp8 bytes are pulled back to host once for the
136	    /// block-scaled dequant, then dropped — it is not stored). Same architecture
137	    /// shape checks as `from_host`.
138	    #[allow(clippy::too_many_arguments)]
139	    pub(crate) fn from_device(
140	        ctx: &DeviceContext,
141	        q_a: ProjWeight,
142	        q_a_ln: DeviceVec,
143	        q_b: ProjWeight,
144	        kv_a: ProjWeight,
145	        kv_a_ln: DeviceVec,
146	        kv_b: &ProjWeight,
147	        o_proj: ProjWeight,
148	    ) -> Result<Self> {
149	        let check = |label: &str, p: &ProjWeight, n: usize, k: usize| -> Result<()> {
150	            ensure!(
151	                p.n == n && p.k == k,
152	                "GLM5.2 {label} shape [{},{}] != [{n},{k}]",
153	                p.n,
154	                p.k
155	            );
156	            Ok(())
157	        };
158	        let heads = mla_heads(q_b.n, kv_b.n, o_proj.k)?;
159	        check("q_a_proj", &q_a, Q_LORA, HIDDEN)?;
160	        check("q_b_proj", &q_b, heads * Q_HEAD, Q_LORA)?;
161	        check("kv_a_proj_with_mqa", &kv_a, KV_A_OUT, HIDDEN)?;
162	        check("kv_b_proj", kv_b, heads * KV_B_ROWS_PER_HEAD, KV_LORA)?;
163	        check("o_proj", &o_proj, HIDDEN, heads * V_HEAD)?;
164	        ensure!(
165	            q_a_ln.len == Q_LORA && kv_a_ln.len == KV_LORA,
166	            "GLM5.2 MLA layernorm lengths q_a_ln {} / kv_a_ln {} != {Q_LORA}/{KV_LORA}",
167	            q_a_ln.len,
168	            kv_a_ln.len
169	        );
170	        let kv_b_weight = ctx.stream.clone_dtoh(&kv_b.weight)?;
171	        let kv_b_scale = ctx.stream.clone_dtoh(&kv_b.scale)?;
172	        let (w_uk, w_uv) = dequant_kv_b(
173	            ctx,
174	            &Glm52ProjBytes {
175	                weight: &kv_b_weight,
176	                scale: &kv_b_scale,
177	                n: kv_b.n,
178	                k: kv_b.k,
179	            },
180	        )?;
181	        let qa_kva = pack_qa_kva(ctx, &q_a, &kv_a)?;
182	        Ok(Self {
183	            q_a,
184	            q_a_ln,
185	            q_b,
186	            kv_a,
187	            kv_a_ln,
188	            o_proj,
189	            w_uk,
190	            w_uv,
191	            qa_kva,
192	            heads,
193	        })
194	    }
195	}
