197	/// The horizontal q_a|kv_a pack, built only where the batched mma table
198	/// routes the packed shape (see the `qa_kva` field comment). The batch-8
199	/// query covers every fused bucket: smaller batches never have a packed
200	/// entry, and the runtime re-checks its own row count before taking the
201	/// fused path.
202	fn pack_qa_kva(
203	    ctx: &DeviceContext,
204	    q_a: &ProjWeight,
205	    kv_a: &ProjWeight,
206	) -> Result<Option<ProjWeight>> {
207	    if !glm52_gemv_mma_routes(crate::fp8::FP8_GEMV_MAX_ROWS, q_a.n + kv_a.n, q_a.k)? {
208	        return Ok(None);
209	    }
210	    Ok(Some(pack_proj_pair(ctx, q_a, kv_a)?))
211	}
212	
213	/// Per-rank bytes the q_a|kv_a packed twins will allocate during rank-model
214	/// build (0 where the mma table has no packed route). The context-cap budget
215	/// subtracts this up front — the twins land after the free-VRAM probe, and an
216	/// unledgered ~1.2 GiB eats the post-build headroom floor. The route query
217	/// reads the LAUNCHING process's device arch; a mixed-arch fleet (`--glm52-ranks`
218	/// spans nodes) could drift from another node's packing, where the post-build
219	/// headroom re-probe is the backstop.
220	pub(crate) fn glm52_qa_kva_twin_bytes() -> Result<usize> {
221	    let n = Q_LORA + KV_A_OUT;
222	    if !glm52_gemv_mma_routes(crate::fp8::FP8_GEMV_MAX_ROWS, n, HIDDEN)? {
223	        return Ok(0);
224	    }
225	    let scale = n.div_ceil(FP8_BLOCK) * HIDDEN.div_ceil(FP8_BLOCK) * 4;
226	    Ok(crate::config::GLM52_LAYERS * (n * HIDDEN + scale))
227	}
