229	/// Derive the head count carried by a (possibly attention-TP-sharded) weight
230	/// set from the q_b/kv_b/o_proj shapes; the three must agree and the FlashMLA
231	/// full width (64) is the ceiling.
232	fn mla_heads(q_b_n: usize, kv_b_n: usize, o_proj_k: usize) -> Result<usize> {
233	    ensure!(
234	        q_b_n.is_multiple_of(Q_HEAD) && q_b_n > 0,
235	        "GLM5.2 q_b_proj n {q_b_n} is not a positive multiple of {Q_HEAD}"
236	    );
237	    let heads = q_b_n / Q_HEAD;
238	    ensure!(
239	        heads <= HEADS,
240	        "GLM5.2 MLA heads {heads} exceeds the architecture's {HEADS}"
241	    );
242	    ensure!(
243	        kv_b_n == heads * KV_B_ROWS_PER_HEAD && o_proj_k == heads * V_HEAD,
244	        "GLM5.2 MLA head-count mismatch: q_b says {heads} heads, kv_b n {kv_b_n} (want {}), o_proj k {o_proj_k} (want {})",
245	        heads * KV_B_ROWS_PER_HEAD,
246	        heads * V_HEAD
247	    );
248	    Ok(heads)
249	}
