300	/// Persistent scratch for the MLA front-half projections of one step's
301	/// `tokens` rows: everything derivable from `hidden` alone, before the sparse
302	/// top-k is known. Written in place by [`glm52_mla_front_into`] every step
303	/// (pointer-stable for graph capture); one instance is shared across all 78
304	/// layers — layer N's values are dead once layer N's attend consumed them.
305	/// `q_resid` is exposed because the DSA indexer consumes it (`wq_b(q_resid)`)
306	/// to *produce* the top-k that the attend half then attends over. The row
307	/// count is baked here so every front kernel derives it from one place.
308	pub(crate) struct Glm52MlaFront {
309	    q_a: CudaSlice<bf16>,             // [T, 2048] pre q_a_layernorm
310	    pub(crate) q_resid: Rows<Q_LORA>, // [T, 2048] post q_a_layernorm
311	    // [T, heads, 256] (compact head shard); read by the attend half.
312	    pub(crate) q_full: CudaSlice<bf16>,
313	    pub(crate) ckv: CudaSlice<bf16>, // [T, 576] = compressed_kv | k_pe
314	    kv_c_raw: CudaSlice<bf16>,       // [T, 512] pre kv_a_layernorm
315	    pub(crate) kv_c: CudaSlice<bf16>, // [T, 512] post kv_a_layernorm
316	    pub(crate) k_pe: CudaSlice<bf16>, // [T, 64] pre-rope
317	    pub(crate) heads: usize,
318	    // Owned mma partial buffer for the front projections (q_a/q_b/kv_a). One
319	    // per scratch struct: the ctx/aux stream overlap must never share one.
320	    gemv_partial: CudaSlice<f32>,
321	    // Validation-only bf16 sink for the packed q_a|kv_a partials launch (the
322	    // route gate guarantees the mma path, which leaves it untouched).
323	    qa_kva_out: CudaSlice<bf16>, // [T, 2624]
324	    // Wide-bucket route (#812): q_a/q_b/kv_a run the fp8 GEMM past the GEMV
325	    // row ceiling. Owned per scratch, like `gemv_partial`.
326	    wide: Option<Glm52Fp8GemmScratch>,
327	}
