329	impl Glm52MlaFront {
330	    pub(crate) fn new(ctx: &DeviceContext, tokens: usize, heads: usize) -> Result<Self> {
331	        Self::with_decode_scratch(ctx, tokens, heads, true)
332	    }
333	
334	    pub(crate) fn new_prefill(ctx: &DeviceContext, tokens: usize, heads: usize) -> Result<Self> {
335	        Self::with_decode_scratch(ctx, tokens, heads, false)
336	    }
337	
338	    fn with_decode_scratch(
339	        ctx: &DeviceContext,
340	        tokens: usize,
341	        heads: usize,
342	        decode_scratch: bool,
343	    ) -> Result<Self> {
344	        ensure!(
345	            (1..=HEADS).contains(&heads),
346	            "GLM5.2 MLA front heads {heads} out of 1..={HEADS}"
347	        );
348	        Ok(Self {
349	            q_a: ctx.stream.alloc_zeros::<bf16>(tokens * Q_LORA)?,
350	            q_resid: Rows::zeros(ctx, tokens)?,
351	            q_full: ctx.stream.alloc_zeros::<bf16>(tokens * heads * Q_HEAD)?,
352	            ckv: ctx.stream.alloc_zeros::<bf16>(tokens * KV_A_OUT)?,
353	            kv_c_raw: ctx.stream.alloc_zeros::<bf16>(tokens * KV_LORA)?,
354	            kv_c: ctx.stream.alloc_zeros::<bf16>(tokens * KV_LORA)?,
355	            k_pe: ctx.stream.alloc_zeros::<bf16>(tokens * ROPE_DIM)?,
356	            heads,
357	            gemv_partial: ctx.stream.alloc_zeros::<f32>(if decode_scratch {
358	                tokens * GLM52_GEMV_MMA_SCRATCH_FLOATS_PER_ROW
359	            } else {
360	                1
361	            })?,
362	            qa_kva_out: ctx.stream.alloc_zeros::<bf16>(if decode_scratch {
363	                tokens * (Q_LORA + KV_A_OUT)
364	            } else {
365	                1
366	            })?,
367	            wide: (decode_scratch && tokens > crate::fp8::FP8_GEMV_MAX_ROWS)
368	                .then(|| {
369	                    // q_a/kv_a consume hidden (k = 6144), q_b consumes Q_LORA.
370	                    Glm52Fp8GemmScratch::new(ctx, tokens.next_multiple_of(4), HIDDEN)
371	                })
372	                .transpose()?,
373	        })
374	    }
375	
376	    /// The step row count every front buffer was sized for.
377	    fn tokens(&self) -> usize {
378	        self.q_resid.tokens()
379	    }
380	}
