382	pub(crate) fn glm52_mla_prefill_front_into(
383	    ctx: &DeviceContext,
384	    weights: &Glm52MlaLayerWeights,
385	    rows: usize,
386	    hidden: &CudaSlice<bf16>,
387	    scratch: &mut Glm52Fp8GemmScratch,
388	    front: &mut Glm52MlaFront,
389	) -> Result<()> {
390	    ensure!(
391	        rows > 0
392	            && rows.is_multiple_of(4)
393	            && rows <= front.tokens()
394	            && weights.heads == front.heads,
395	        "GLM5.2 prefill MLA front shape mismatch"
396	    );
397	    fp8_linear_large_m_into(ctx, &weights.q_a, rows, hidden, scratch, &mut front.q_a)?;
398	    rms_norm_rows_into(
399	        ctx,
400	        &front.q_a,
401	        &weights.q_a_ln,
402	        RMS_EPS,
403	        Q_LORA,
404	        rows,
405	        front.q_resid.data_mut(),
406	    )?;
407	    fp8_linear_large_m_into(
408	        ctx,
409	        &weights.q_b,
410	        rows,
411	        front.q_resid.data(),
412	        scratch,
413	        &mut front.q_full,
414	    )?;
415	    fp8_linear_large_m_into(ctx, &weights.kv_a, rows, hidden, scratch, &mut front.ckv)?;
416	    glm52_mla_ckv_split_launch(ctx, rows, &front.ckv, &mut front.kv_c_raw, &mut front.k_pe)?;
417	    rms_norm_rows_into(
418	        ctx,
419	        &front.kv_c_raw,
420	        &weights.kv_a_ln,
421	        RMS_EPS,
422	        KV_LORA,
423	        rows,
424	        &mut front.kv_c,
425	    )
426	}
