428	/// The q-phase of the MLA front: `q_a` projection + q_a_layernorm over the
429	/// front's `tokens` rows. Split out because `q_resid` is everything the DSA
430	/// indexer needs — the caller can fork the indexer onto an aux stream right
431	/// after this and run [`glm52_mla_front_rest_into`] concurrently.
432	pub(crate) fn glm52_mla_front_q_into(
433	    ctx: &DeviceContext,
434	    w: &Glm52MlaLayerWeights,
435	    hidden: &Rows<HIDDEN>,
436	    front: &mut Glm52MlaFront,
437	) -> Result<()> {
438	    let t = front.tokens();
439	    if t == 1 {
440	        // q_a and kv_a share `hidden`. On bs=1 one concatenated grid removes
441	        // a graph node while keeping both checkpoint weights/output buffers.
442	        fp8_linear_pair_into(
443	            ctx,
444	            &w.q_a,
445	            &w.kv_a,
446	            hidden.data(),
447	            &mut front.q_a,
448	            &mut front.ckv,
449	        )?;
450	    } else if let Some(qa_kva) = qa_kva_fused(w, t)? {
451	        // One batched launch over the packed weight computes q_a AND kv_a
452	        // (see the `qa_kva` field comment); the split-reduce de-interleaves
453	        // the partials into the compact q_a/ckv buffers every downstream
454	        // consumer expects. `front_rest` skips its kv_a launch (same
455	        // `qa_kva_fused` predicate).
456	        let ksplit = fp8_linear_partials_into(
457	            ctx,
458	            qa_kva,
459	            t,
460	            hidden.data(),
461	            &mut front.gemv_partial,
462	            &mut front.qa_kva_out,
463	        )?;
464	        ensure!(
465	            ksplit > 0,
466	            "GLM5.2 packed q_a|kv_a launch took the register tile despite the route gate"
467	        );
468	        glm52_gemv_split_reduce_launch(
469	            ctx,
470	            t,
471	            Q_LORA,
472	            KV_A_OUT,
473	            ksplit,
474	            &front.gemv_partial,
475	            &mut front.q_a,
476	            &mut front.ckv,
477	        )?;
478	    } else if let Some(wide) = front.wide.as_mut() {
479	        if let Some(qa_kva) = w.qa_kva.as_ref() {
480	            // One packed GEMM computes q_a AND kv_a from ONE quantization of
481	            // `hidden` — the #812 profile showed the wide step dominated by
482	            // skinny per-projection GEMMs plus their activation quants; the
483	            // pack halves both for this pair. `front_rest` skips its kv_a
484	            // launch (same `qa_kva_packed_wide` predicate).
485	            fp8_linear_large_m_into(ctx, qa_kva, t, hidden.data(), wide, &mut front.qa_kva_out)?;
486	            extract_hidden_rows_raw_into(
487	                ctx,
488	                &front.qa_kva_out,
489	                Q_LORA + KV_A_OUT,
490	                &mut front.q_a,
491	                Q_LORA,
492	                0,
493	                t,
494	            )?;
495	            extract_hidden_rows_raw_into(
496	                ctx,
497	                &front.qa_kva_out,
498	                Q_LORA + KV_A_OUT,
499	                &mut front.ckv,
500	                KV_A_OUT,
501	                Q_LORA,
502	                t,
503	            )?;
504	        } else {
505	            fp8_linear_large_m_into(ctx, &w.q_a, t, hidden.data(), wide, &mut front.q_a)?;
506	        }
507	    } else {
508	        fp8_linear_into(
509	            ctx,
510	            &w.q_a,
511	            t,
512	            hidden.data(),
513	            Some(&mut front.gemv_partial),
514	            &mut front.q_a,
515	        )?;
516	    }
517	    rms_norm_rows_into(
518	        ctx,
519	        &front.q_a,
520	        &w.q_a_ln,
521	        RMS_EPS,
522	        Q_LORA,
523	        t,
524	        front.q_resid.data_mut(),
525	    )
526	}
527	
528	/// The packed q_a|kv_a weight, iff this row count routes to the batched mma
529	/// path — the ONE predicate both front halves consult (front_q takes the
530	/// fused launch, front_rest skips its kv_a).
531	fn qa_kva_fused(w: &Glm52MlaLayerWeights, t: usize) -> Result<Option<&ProjWeight>> {
532	    let Some(qa_kva) = w.qa_kva.as_ref() else {
533	        return Ok(None);
534	    };
535	    Ok(glm52_gemv_mma_routes(t, qa_kva.n, qa_kva.k)?.then_some(qa_kva))
536	}
537	
538	/// Whether the wide-bucket route already computed kv_a through the packed
539	/// q_a|kv_a GEMM (#812) — front_rest's twin of [`qa_kva_fused`].
540	fn qa_kva_packed_wide(w: &Glm52MlaLayerWeights, front: &Glm52MlaFront) -> bool {
541	    w.qa_kva.is_some() && front.wide.is_some()
542	}
543	
544	/// The remainder of the MLA front: q_b + kv_a projections and the kv_c/k_pe
545	/// unpacking, over the front's `tokens` rows. Independent of the indexer.
546	///
547	/// `fold_kv_pack` (the FlashInfer backend): the ckv split and kv_a RMSNorm
548	/// are fused into the attend-side `glm52_mla_front_pack_fp8_launch`, so this
549	/// half leaves `front.ckv` raw and never touches kv_c/k_pe.
550	pub(crate) fn glm52_mla_front_rest_into(
551	    ctx: &DeviceContext,
552	    w: &Glm52MlaLayerWeights,
553	    hidden: &Rows<HIDDEN>,
554	    front: &mut Glm52MlaFront,
555	    fold_kv_pack: bool,
556	) -> Result<()> {
557	    let t = front.tokens();
558	    ensure!(
559	        w.heads == front.heads,
560	        "GLM5.2 MLA front sized for {} heads but weights carry {}",
561	        front.heads,
562	        w.heads
563	    );
564	    if let Some(wide) = front.wide.as_mut() {
565	        fp8_linear_large_m_into(
566	            ctx,
567	            &w.q_b,
568	            t,
569	            front.q_resid.data(),
570	            wide,
571	            &mut front.q_full,
572	        )?;
573	    } else {
574	        fp8_linear_into(
575	            ctx,
576	            &w.q_b,
577	            t,
578	            front.q_resid.data(),
579	            Some(&mut front.gemv_partial),
580	            &mut front.q_full,
581	        )?; // [T, heads, 256]
582	    }
583	    if t != 1 && qa_kva_fused(w, t)?.is_none() && !qa_kva_packed_wide(w, front) {
584	        if let Some(wide) = front.wide.as_mut() {
585	            fp8_linear_large_m_into(ctx, &w.kv_a, t, hidden.data(), wide, &mut front.ckv)?;
586	        } else {
587	            fp8_linear_into(
588	                ctx,
589	                &w.kv_a,
590	                t,
591	                hidden.data(),
592	                Some(&mut front.gemv_partial),
593	                &mut front.ckv,
594	            )?;
595	        }
596	    }
597	    if fold_kv_pack {
598	        return Ok(());
599	    }
600	    glm52_mla_ckv_split_launch(ctx, t, &front.ckv, &mut front.kv_c_raw, &mut front.k_pe)?;
601	    rms_norm_rows_into(
602	        ctx,
603	        &front.kv_c_raw,
604	        &w.kv_a_ln,
605	        RMS_EPS,
606	        KV_LORA,
607	        t,
608	        &mut front.kv_c,
609	    )
610	}
611	
612	/// MLA front half: fp8 projections + norms from `hidden[T, 6144]` into the
613	/// persistent front scratch.
614	#[cfg(test)]
615	pub(crate) fn glm52_mla_front_into(
616	    ctx: &DeviceContext,
617	    w: &Glm52MlaLayerWeights,
618	    hidden: &Rows<HIDDEN>,
619	    front: &mut Glm52MlaFront,
620	    fold_kv_pack: bool,
621	) -> Result<()> {
622	    glm52_mla_front_q_into(ctx, w, hidden, front)?;
623	    glm52_mla_front_rest_into(ctx, w, hidden, front, fold_kv_pack)
624	}
625

