166	            "GLM5.2 MLA layernorm lengths q_a_ln {} / kv_a_ln {} != {Q_LORA}/{KV_LORA}",
167	            q_a_ln.len,
168	            kv_a_ln.len
169	        );
170	        let kv_b_weight = ctx.stream.clone_dtoh(&kv_b.weight)?;
171	        let kv_b_scale = ctx.stream.clone_dtoh(&kv_b.scale)?;
172	        let (w_uk, w_uv) = dequant_kv_b(
173	            ctx,
174	            &Glm52ProjBytes {
175	                weight: &kv_b_weight,
176	                scale: &kv_b_scale,
177	                n: kv_b.n,
178	                k: kv_b.k,
179	            },
180	        )?;
181	        let qa_kva = pack_qa_kva(ctx, &q_a, &kv_a)?;
182	        Ok(Self {
183	            q_a,
184	            q_a_ln,
185	            q_b,
186	            kv_a,
187	            kv_a_ln,
188	            o_proj,
189	            w_uk,
190	            w_uv,
191	            qa_kva,
192	            heads,
193	        })
194	    }
195	}
196	
197	/// The horizontal q_a|kv_a pack, built only where the batched mma table
198	/// routes the packed shape (see the `qa_kva` field comment). The batch-8
199	/// query covers every fused bucket: smaller batches never have a packed
200	/// entry, and the runtime re-checks its own row count before taking the
201	/// fused path.
202	fn pack_qa_kva(
203	    ctx: &DeviceContext,
204	    q_a: &ProjWeight,
205	    kv_a: &ProjWeight,
206	) -> Result<Option<ProjWeight>> {
207	    if !glm52_gemv_mma_routes(crate::fp8::FP8_GEMV_MAX_ROWS, q_a.n + kv_a.n, q_a.k)? {
208	        return Ok(None);
209	    }
210	    Ok(Some(pack_proj_pair(ctx, q_a, kv_a)?))
211	}
212	
213	/// Per-rank bytes the q_a|kv_a packed twins will allocate during rank-model
214	/// build (0 where the mma table has no packed route). The context-cap budget
215	/// subtracts this up front — the twins land after the free-VRAM probe, and an
216	/// unledgered ~1.2 GiB eats the post-build headroom floor. The route query
217	/// reads the LAUNCHING process's device arch; a mixed-arch fleet (`--glm52-ranks`
218	/// spans nodes) could drift from another node's packing, where the post-build
219	/// headroom re-probe is the backstop.
220	pub(crate) fn glm52_qa_kva_twin_bytes() -> Result<usize> {
221	    let n = Q_LORA + KV_A_OUT;
222	    if !glm52_gemv_mma_routes(crate::fp8::FP8_GEMV_MAX_ROWS, n, HIDDEN)? {
223	        return Ok(0);
224	    }
225	    let scale = n.div_ceil(FP8_BLOCK) * HIDDEN.div_ceil(FP8_BLOCK) * 4;
226	    Ok(crate::config::GLM52_LAYERS * (n * HIDDEN + scale))
227	}
228	
229	/// Derive the head count carried by a (possibly attention-TP-sharded) weight
230	/// set from the q_b/kv_b/o_proj shapes; the three must agree and the FlashMLA
231	/// full width (64) is the ceiling.
232	fn mla_heads(q_b_n: usize, kv_b_n: usize, o_proj_k: usize) -> Result<usize> {
233	    ensure!(
234	        q_b_n.is_multiple_of(Q_HEAD) && q_b_n > 0,
235	        "GLM5.2 q_b_proj n {q_b_n} is not a positive multiple of {Q_HEAD}"
236	    );
237	    let heads = q_b_n / Q_HEAD;
238	    ensure!(
239	        heads <= HEADS,
240	        "GLM5.2 MLA heads {heads} exceeds the architecture's {HEADS}"
241	    );
242	    ensure!(
243	        kv_b_n == heads * KV_B_ROWS_PER_HEAD && o_proj_k == heads * V_HEAD,
244	        "GLM5.2 MLA head-count mismatch: q_b says {heads} heads, kv_b n {kv_b_n} (want {}), o_proj k {o_proj_k} (want {})",
245	        heads * KV_B_ROWS_PER_HEAD,
246	        heads * V_HEAD
247	    );
248	    Ok(heads)
249	}
250	
251	/// Host-dequant kv_b (fp8 e4m3 block-scaled) into bf16 W_UK [heads,192,512]
252	/// (nope) and W_UV [heads,256,512] (v) absorb factors, head-major, uploaded
253	/// to device. The head count follows kv_b.n (full 64 or an attention-TP
254	/// shard whose rows were sliced upstream).
255	fn dequant_kv_b(
256	    ctx: &DeviceContext,
257	    kv_b: &Glm52ProjBytes,
258	) -> Result<(CudaSlice<bf16>, CudaSlice<bf16>)> {
259	    let heads = kv_b.n / KV_B_ROWS_PER_HEAD;
260	    // kv_b is indexed raw below (it does not pass through ProjWeight::upload), so
261	    // self-defend its byte lengths here — a truncated blob must error, not panic.
262	    ensure!(
263	        kv_b.weight.len() == kv_b.n * kv_b.k,
264	        "GLM5.2 kv_b weight bytes {} != n*k {}",
265	        kv_b.weight.len(),
266	        kv_b.n * kv_b.k
267	    );
268	    ensure!(
269	        kv_b.scale.len() == kv_b.n.div_ceil(FP8_BLOCK) * kv_b.k.div_ceil(FP8_BLOCK) * 4,
270	        "GLM5.2 kv_b scale bytes {} unexpected for [{},{}]",
271	        kv_b.scale.len(),
272	        kv_b.n,
273	        kv_b.k
274	    );
275	    let scale_cols = KV_LORA / FP8_BLOCK;
276	    let scale = bytes_to_f32(kv_b.scale);
277	    let mut w_uk = vec![bf16::from_f32(0.0); heads * QK_NOPE * KV_LORA];
278	    let mut w_uv = vec![bf16::from_f32(0.0); heads * V_HEAD * KV_LORA];
279	    for h in 0..heads {
280	        for r in 0..KV_B_ROWS_PER_HEAD {
281	            let row = h * KV_B_ROWS_PER_HEAD + r;
282	            for j in 0..KV_LORA {
283	                let s = scale[(row / FP8_BLOCK) * scale_cols + j / FP8_BLOCK];
284	                let val = bf16::from_f32(e4m3_to_f32(kv_b.weight[row * KV_LORA + j]) * s);
285	                if r < QK_NOPE {
286	                    w_uk[(h * QK_NOPE + r) * KV_LORA + j] = val;
287	                } else {
288	                    w_uv[(h * V_HEAD + (r - QK_NOPE)) * KV_LORA + j] = val;
289	                }
290	            }
291	        }
292	    }
293	    let mut uk = ctx.stream.alloc_zeros::<bf16>(w_uk.len())?;
294	    let mut uv = ctx.stream.alloc_zeros::<bf16>(w_uv.len())?;
295	    ctx.stream.memcpy_htod(&w_uk, &mut uk)?;
296	    ctx.stream.memcpy_htod(&w_uv, &mut uv)?;
297	    Ok((uk, uv))
298	}
299	
300	/// Persistent scratch for the MLA front-half projections of one step's
301	/// `tokens` rows: everything derivable from `hidden` alone, before the sparse
302	/// top-k is known. Written in place by [`glm52_mla_front_into`] every step
303	/// (pointer-stable for graph capture); one instance is shared across all 78
304	/// layers — layer N's values are dead once layer N's attend consumed them.
305	/// `q_resid` is exposed because the DSA indexer consumes it (`wq_b(q_resid)`)
306	/// to *produce* the top-k that the attend half then attends over. The row
307	/// count is baked here so every front kernel derives it from one place.
308	pub(crate) struct Glm52MlaFront {
309	    q_a: CudaSlice<bf16>,             // [T, 2048] pre q_a_layernorm
310	    pub(crate) q_resid: Rows<Q_LORA>, // [T, 2048] post q_a_layernorm
311	    // [T, heads, 256] (compact head shard); read by the attend half.
312	    pub(crate) q_full: CudaSlice<bf16>,
313	    pub(crate) ckv: CudaSlice<bf16>, // [T, 576] = compressed_kv | k_pe
314	    kv_c_raw: CudaSlice<bf16>,       // [T, 512] pre kv_a_layernorm
315	    pub(crate) kv_c: CudaSlice<bf16>, // [T, 512] post kv_a_layernorm
316	    pub(crate) k_pe: CudaSlice<bf16>, // [T, 64] pre-rope
317	    pub(crate) heads: usize,
318	    // Owned mma partial buffer for the front projections (q_a/q_b/kv_a). One
319	    // per scratch struct: the ctx/aux stream overlap must never share one.
320	    gemv_partial: CudaSlice<f32>,
321	    // Validation-only bf16 sink for the packed q_a|kv_a partials launch (the
322	    // route gate guarantees the mma path, which leaves it untouched).
323	    qa_kva_out: CudaSlice<bf16>, // [T, 2624]
324	    // Wide-bucket route (#812): q_a/q_b/kv_a run the fp8 GEMM past the GEMV
325	    // row ceiling. Owned per scratch, like `gemv_partial`.
326	    wide: Option<Glm52Fp8GemmScratch>,
327	}
328	
329	impl Glm52MlaFront {
330	    pub(crate) fn new(ctx: &DeviceContext, tokens: usize, heads: usize) -> Result<Self> {
331	        Self::with_decode_scratch(ctx, tokens, heads, true)
332	    }
333	
334	    pub(crate) fn new_prefill(ctx: &DeviceContext, tokens: usize, heads: usize) -> Result<Self> {
335	        Self::with_decode_scratch(ctx, tokens, heads, false)
336	    }
337	
338	    fn with_decode_scratch(
339	        ctx: &DeviceContext,
340	        tokens: usize,
341	        heads: usize,
342	        decode_scratch: bool,
343	    ) -> Result<Self> {
344	        ensure!(
345	            (1..=HEADS).contains(&heads),
346	            "GLM5.2 MLA front heads {heads} out of 1..={HEADS}"
347	        );
348	        Ok(Self {
349	            q_a: ctx.stream.alloc_zeros::<bf16>(tokens * Q_LORA)?,
350	            q_resid: Rows::zeros(ctx, tokens)?,
351	            q_full: ctx.stream.alloc_zeros::<bf16>(tokens * heads * Q_HEAD)?,
352	            ckv: ctx.stream.alloc_zeros::<bf16>(tokens * KV_A_OUT)?,
353	            kv_c_raw: ctx.stream.alloc_zeros::<bf16>(tokens * KV_LORA)?,
354	            kv_c: ctx.stream.alloc_zeros::<bf16>(tokens * KV_LORA)?,
355	            k_pe: ctx.stream.alloc_zeros::<bf16>(tokens * ROPE_DIM)?,
356	            heads,
357	            gemv_partial: ctx.stream.alloc_zeros::<f32>(if decode_scratch {
358	                tokens * GLM52_GEMV_MMA_SCRATCH_FLOATS_PER_ROW
359	            } else {
360	                1
361	            })?,
362	            qa_kva_out: ctx.stream.alloc_zeros::<bf16>(if decode_scratch {
363	                tokens * (Q_LORA + KV_A_OUT)
364	            } else {
365	                1
366	            })?,
367	            wide: (decode_scratch && tokens > crate::fp8::FP8_GEMV_MAX_ROWS)
368	                .then(|| {
369	                    // q_a/kv_a consume hidden (k = 6144), q_b consumes Q_LORA.
370	                    Glm52Fp8GemmScratch::new(ctx, tokens.next_multiple_of(4), HIDDEN)
371	                })
372	                .transpose()?,
373	        })
374	    }
375	
376	    /// The step row count every front buffer was sized for.
377	    fn tokens(&self) -> usize {
378	        self.q_resid.tokens()
379	    }
380	}
381	
382	pub(crate) fn glm52_mla_prefill_front_into(
383	    ctx: &DeviceContext,
384	    weights: &Glm52MlaLayerWeights,
385	    rows: usize,
386	    hidden: &CudaSlice<bf16>,
387	    scratch: &mut Glm52Fp8GemmScratch,
388	    front: &mut Glm52MlaFront,
389	) -> Result<()> {
390	    ensure!(
391	        rows > 0
392	            && rows.is_multiple_of(4)
393	            && rows <= front.tokens()
394	            && weights.heads == front.heads,
395	        "GLM5.2 prefill MLA front shape mismatch"
396	    );
397	    fp8_linear_large_m_into(ctx, &weights.q_a, rows, hidden, scratch, &mut front.q_a)?;
398	    rms_norm_rows_into(
399	        ctx,
400	        &front.q_a,
401	        &weights.q_a_ln,
402	        RMS_EPS,
403	        Q_LORA,
404	        rows,
405	        front.q_resid.data_mut(),
406	    )?;
407	    fp8_linear_large_m_into(
408	        ctx,
409	        &weights.q_b,
410	        rows,
411	        front.q_resid.data(),
412	        scratch,
413	        &mut front.q_full,
414	    )?;
415	    fp8_linear_large_m_into(ctx, &weights.kv_a, rows, hidden, scratch, &mut front.ckv)?;
416	    glm52_mla_ckv_split_launch(ctx, rows, &front.ckv, &mut front.kv_c_raw, &mut front.k_pe)?;
417	    rms_norm_rows_into(
418	        ctx,
419	        &front.kv_c_raw,
420	        &weights.kv_a_ln,
421	        RMS_EPS,
422	        KV_LORA,
423	        rows,
424	        &mut front.kv_c,
425	    )
426	}
427	
428	/// The q-phase of the MLA front: `q_a` projection + q_a_layernorm over the
429	/// front's `tokens` rows. Split out because `q_resid` is everything the DSA
430	/// indexer needs — the caller can fork the indexer onto an aux stream right
431	/// after this and run [`glm52_mla_front_rest_into`] concurrently.
432	pub(crate) fn glm52_mla_front_q_into(
433	    ctx: &DeviceContext,
434	    w: &Glm52MlaLayerWeights,
435	    hidden: &Rows<HIDDEN>,
436	    front: &mut Glm52MlaFront,
437	) -> Result<()> {
438	    let t = front.tokens();
439	    if t == 1 {
440	        // q_a and kv_a share `hidden`. On bs=1 one concatenated grid removes
441	        // a graph node while keeping both checkpoint weights/output buffers.
442	        fp8_linear_pair_into(
443	            ctx,
444	            &w.q_a,
445	            &w.kv_a,
446	            hidden.data(),
447	            &mut front.q_a,
448	            &mut front.ckv,
449	        )?;
450	    } else if let Some(qa_kva) = qa_kva_fused(w, t)? {
451	        // One batched launch over the packed weight computes q_a AND kv_a
452	        // (see the `qa_kva` field comment); the split-reduce de-interleaves
453	        // the partials into the compact q_a/ckv buffers every downstream
454	        // consumer expects. `front_rest` skips its kv_a launch (same
455	        // `qa_kva_fused` predicate).
456	        let ksplit = fp8_linear_partials_into(
457	            ctx,
458	            qa_kva,
459	            t,
460	            hidden.data(),
461	            &mut front.gemv_partial,
462	            &mut front.qa_kva_out,
463	        )?;
464	        ensure!(
465	            ksplit > 0,
466	            "GLM5.2 packed q_a|kv_a launch took the register tile despite the route gate"
467	        );
468	        glm52_gemv_split_reduce_launch(
469	            ctx,
470	            t,
471	            Q_LORA,
472	            KV_A_OUT,
473	            ksplit,
474	            &front.gemv_partial,
475	            &mut front.q_a,
476	            &mut front.ckv,
477	        )?;
478	    } else if let Some(wide) = front.wide.as_mut() {
479	        if let Some(qa_kva) = w.qa_kva.as_ref() {
480	            // One packed GEMM computes q_a AND kv_a from ONE quantization of
481	            // `hidden` — the #812 profile showed the wide step dominated by
482	            // skinny per-projection GEMMs plus their activation quants; the
483	            // pack halves both for this pair. `front_rest` skips its kv_a
484	            // launch (same `qa_kva_packed_wide` predicate).
485	            fp8_linear_large_m_into(ctx, qa_kva, t, hidden.data(), wide, &mut front.qa_kva_out)?;
486	            extract_hidden_rows_raw_into(
487	                ctx,
488	                &front.qa_kva_out,
489	                Q_LORA + KV_A_OUT,
490	                &mut front.q_a,
491	                Q_LORA,
492	                0,
493	                t,
494	            )?;
495	            extract_hidden_rows_raw_into(
496	                ctx,
497	                &front.qa_kva_out,
498	                Q_LORA + KV_A_OUT,
499	                &mut front.ckv,
500	                KV_A_OUT,
501	                Q_LORA,
502	                t,
503	            )?;
504	        } else {
505	            fp8_linear_large_m_into(ctx, &w.q_a, t, hidden.data(), wide, &mut front.q_a)?;
506	        }
507	    } else {
508	        fp8_linear_into(
509	            ctx,
510	            &w.q_a,
511	            t,
512	            hidden.data(),
513	            Some(&mut front.gemv_partial),
514	            &mut front.q_a,
515	        )?;
516	    }
517	    rms_norm_rows_into(
518	        ctx,
519	        &front.q_a,
520	        &w.q_a_ln,
521	        RMS_EPS,
522	        Q_LORA,
523	        t,
524	        front.q_resid.data_mut(),
525	    )
526	}
527	
528	/// The packed q_a|kv_a weight, iff this row count routes to the batched mma
529	/// path — the ONE predicate both front halves consult (front_q takes the
530	/// fused launch, front_rest skips its kv_a).
531	fn qa_kva_fused(w: &Glm52MlaLayerWeights, t: usize) -> Result<Option<&ProjWeight>> {
532	    let Some(qa_kva) = w.qa_kva.as_ref() else {
533	        return Ok(None);
534	    };
535	    Ok(glm52_gemv_mma_routes(t, qa_kva.n, qa_kva.k)?.then_some(qa_kva))
536	}
537	
538	/// Whether the wide-bucket route already computed kv_a through the packed
539	/// q_a|kv_a GEMM (#812) — front_rest's twin of [`qa_kva_fused`].
540	fn qa_kva_packed_wide(w: &Glm52MlaLayerWeights, front: &Glm52MlaFront) -> bool {
541	    w.qa_kva.is_some() && front.wide.is_some()
542	}
543	
544	/// The remainder of the MLA front: q_b + kv_a projections and the kv_c/k_pe
545	/// unpacking, over the front's `tokens` rows. Independent of the indexer.
546	///
547	/// `fold_kv_pack` (the FlashInfer backend): the ckv split and kv_a RMSNorm
548	/// are fused into the attend-side `glm52_mla_front_pack_fp8_launch`, so this
549	/// half leaves `front.ckv` raw and never touches kv_c/k_pe.
550	pub(crate) fn glm52_mla_front_rest_into(
551	    ctx: &DeviceContext,
552	    w: &Glm52MlaLayerWeights,
553	    hidden: &Rows<HIDDEN>,
554	    front: &mut Glm52MlaFront,
555	    fold_kv_pack: bool,
556	) -> Result<()> {
557	    let t = front.tokens();
558	    ensure!(
559	        w.heads == front.heads,
560	        "GLM5.2 MLA front sized for {} heads but weights carry {}",
561	        front.heads,
562	        w.heads
563	    );
564	    if let Some(wide) = front.wide.as_mut() {
565	        fp8_linear_large_m_into(
566	            ctx,
567	            &w.q_b,
568	            t,
569	            front.q_resid.data(),
570	            wide,
571	            &mut front.q_full,
572	        )?;
573	    } else {
574	        fp8_linear_into(
575	            ctx,
576	            &w.q_b,
577	            t,
578	            front.q_resid.data(),
579	            Some(&mut front.gemv_partial),
580	            &mut front.q_full,
581	        )?; // [T, heads, 256]
582	    }
583	    if t != 1 && qa_kva_fused(w, t)?.is_none() && !qa_kva_packed_wide(w, front) {
584	        if let Some(wide) = front.wide.as_mut() {
585	            fp8_linear_large_m_into(ctx, &w.kv_a, t, hidden.data(), wide, &mut front.ckv)?;
586	        } else {
587	            fp8_linear_into(
588	                ctx,
589	                &w.kv_a,
590	                t,
591	                hidden.data(),
592	                Some(&mut front.gemv_partial),
593	                &mut front.ckv,
594	            )?;
595	        }
596	    }
597	    if fold_kv_pack {
598	        return Ok(());
599	    }
600	    glm52_mla_ckv_split_launch(ctx, t, &front.ckv, &mut front.kv_c_raw, &mut front.k_pe)?;
601	    rms_norm_rows_into(
602	        ctx,
603	        &front.kv_c_raw,
604	        &w.kv_a_ln,
605	        RMS_EPS,
606	        KV_LORA,
607	        t,
608	        &mut front.kv_c,
609	    )
610	}
611	
612	/// MLA front half: fp8 projections + norms from `hidden[T, 6144]` into the
613	/// persistent front scratch.
614	#[cfg(test)]
615	pub(crate) fn glm52_mla_front_into(
616	    ctx: &DeviceContext,
617	    w: &Glm52MlaLayerWeights,
618	    hidden: &Rows<HIDDEN>,
619	    front: &mut Glm52MlaFront,
620	    fold_kv_pack: bool,
621	) -> Result<()> {
622	    glm52_mla_front_q_into(ctx, w, hidden, front)?;
623	    glm52_mla_front_rest_into(ctx, w, hidden, front, fold_kv_pack)
624	}
