    /// the allocator.
    sampling_scratch: Option<BatchSamplingScratch>,
    /// TP4 eager-prefill executor and reusable 32-row workspace. Persistent
    /// KV lives in `caches`.
    prefill: Option<Glm52TpPrefillExecutor>,
    /// In-flight speculative next-step replay, if any (see `decode_step`).
    speculated: Option<Glm52SpeculatedStep>,
    /// What the per-row `positions` device buffer currently holds (padding
    /// rows included): the feed kernel advances it without host readback,
    /// and a speculation must keep every row under the model-length cap.
    device_positions: [usize; GLM52_MAX_STEP_ROWS],
}

/// Everything one decode bucket owns: the MLA schedule and whole-step
/// graph, shared scratch, and the device block table.
struct Glm52BucketState {
    rows: usize,
    sched: Glm52MlaSchedMetadata,
    scratch: Glm52DecodeScratch,
    graph: CudaGraphState,
    block_table: CudaSlice<i32>,
    /// Pinned landing buffers for this bucket's argmax D2H, sized exactly
    /// `rows` (`memcpy_dtoh` copies the DESTINATION's byte count). Pinned
    /// memory keeps the copy asynchronous so the next step's replay can be
    /// enqueued launch-ahead before the host blocks on the result.
    argmax_values_host: PinnedHostSlice<bf16>,
    argmax_indices_host: PinnedHostSlice<i32>,
}

/// The output of [`Glm52RankModel::build_fixed`]: every len/chunk-scaled
/// piece of a rank model, built BEFORE the pool block count exists so launch
/// can measure the fixed footprint and size the pool from real free VRAM.
/// [`Glm52RankModel::finish_kv`] consumes it. Field meanings match the
/// [`Glm52RankModel`] fields of the same name.
pub(crate) struct Glm52RankModelFixed {
    layers: Vec<Glm52DecoderLayerWeights>,
    mtp: Option<Glm52NativeMtpFixed>,
    embed: DeviceMatrix,
    final_norm: DeviceVec,
    lm_head: DeviceMatrix,
    decode_lm_head: Option<DeviceMatrix>,
    decode_vocab_start: usize,
    /// Built against a 1-block placeholder cache geometry (nothing in a
    /// bucket's allocations scales with the pool); finish_kv rebinds the
    /// sched contract and MQA shape to the decided count.
    buckets: Vec<Glm52BucketState>,
    table_width: usize,
    max_model_len: usize,
    mla_backend: crate::mla_decode::Glm52MlaBackend,
    mla_cache_bytes_per_token: usize,
    ep_ranks: usize,
    slot_mapping: CudaSlice<i64>,
    seq_lens: CudaSlice<i32>,
    cos_table: DeviceMatrix,
    sin_table: DeviceMatrix,
    positions: CudaSlice<u32>,
    cos: CudaSlice<bf16>,
    sin: CudaSlice<bf16>,
    token_ids: CudaSlice<u32>,
    sampling_scratch: Option<BatchSamplingScratch>,
    /// Chunk-scaled workspace only; its pool-scaled unpacked-KV buffers are
    /// attached in finish_kv.
    prefill: Option<Glm52TpPrefillExecutor>,
}

impl Glm52RankModel {
    /// Export one already pre-captured whole-step bucket graph. The scheduler
    /// selects the topology's serving shape; this method only enforces that
    /// the requested bucket belongs to this model and is ready for replay.
    pub(crate) fn dump_decode_graph_png(
        &self,
        bucket: usize,
        png_path: &std::path::Path,
        title: &str,
    ) -> Result<CudaGraphDumpSummary> {
        let state = self
            .buckets
            .iter()
            .find(|state| state.rows == bucket)
            .with_context(|| {

    pub(crate) tp_mlp_out: CudaSlice<bf16>,
    pub(crate) layer: Glm52LayerScratch,
    /// The residual stream: embed writes it, every layer reads and rewrites
    /// it, the final norm consumes it.
    pub(crate) hidden: Rows<GLM52_HIDDEN>,
    /// Optional DSpark aux-hidden capture: each row's residual stream after the
    /// [`crate::dspark::GLM52_DSPARK_AUX_LAYERS`] layers, concatenated per row
    /// (`[tokens, 5 * GLM52_HIDDEN]`). Present only when the drafter was
    /// requested at launch; otherwise neither the buffer nor its five graph
    /// copy nodes exist.
    pub(crate) captured: Option<Rows<GLM52_DSPARK_CONTEXT_DIM>>,
    pub(crate) final_normed: Rows<GLM52_HIDDEN>,
    pub(crate) logits: Rows<GLM52_VOCAB>,
    /// Device greedy argmax outputs: each row's top logit bf16 value (for the
    /// crash-early non-finite guard) and its index — the step's per-row
    /// 6-byte D2H egress. The two-stage argmax stages per-4096-tile partials
    /// first.
    pub(crate) argmax_partial_values: CudaSlice<f32>,
    pub(crate) argmax_partial_indices: CudaSlice<i32>,
    pub(crate) argmax_values: CudaSlice<bf16>,
    pub(crate) argmax_indices: CudaSlice<i32>,
}

impl Glm52DecodeScratch {
    #[cfg(test)]
    pub(crate) fn new(
        ctx: &DeviceContext,
        contract: &Glm52FlashMlaSparseDecode,
        mqa_shape: Glm52DeepGemmMqaLogitsShape,
        mla_heads: usize,
        dspark_enabled: bool,
    ) -> Result<Self> {
        Self::new_for_backend(
            ctx,
            contract,
            mqa_shape,
            mla_heads,
            Glm52MlaBackend::FlashMlaFp8Ds,
            dspark_enabled,
        )
    }

    pub(crate) fn new_for_backend(
        ctx: &DeviceContext,
        contract: &Glm52FlashMlaSparseDecode,
        mqa_shape: Glm52DeepGemmMqaLogitsShape,
        mla_heads: usize,
        mla_backend: Glm52MlaBackend,
        dspark_enabled: bool,
    ) -> Result<Self> {
        let tokens = contract.batch_size;
        anyhow::ensure!(
            mqa_shape.batch_size == tokens,
            "GLM5.2 decode scratch: MQA batch {} != attend batch {tokens}",
            mqa_shape.batch_size
        );
        Ok(Self {
            mla_front: Glm52MlaFront::new(ctx, tokens, mla_heads)?,
            mla_attend: Glm52MlaAttendScratch::new_for_backend(
                ctx,
                contract,
                mla_heads,
                mla_backend,
            )?,
            idx: Glm52IndexerScratch::new(ctx, mqa_shape)?,
            dense_mlp: Glm52MlpScratch::new(ctx, GLM52_DENSE_INTERMEDIATE, tokens)?,
            shared_mlp: Glm52MlpScratch::new(ctx, GLM52_SHARED_EXPERT_INTERMEDIATE, tokens)?,
            router: Glm52RouterScratch::new(ctx, tokens)?,
            tp_normed2: ctx
                .stream
                .alloc_zeros::<bf16>(GLM52_TP_TOKENS * GLM52_HIDDEN)?,
            tp_mlp_out: ctx
                .stream
                .alloc_zeros::<bf16>(GLM52_TP_TOKENS * GLM52_HIDDEN)?,
            layer: Glm52LayerScratch::new(ctx, tokens)?,
            hidden: Rows::zeros(ctx, tokens)?,
            captured: dspark_enabled
                .then(|| Rows::zeros(ctx, tokens))
                .transpose()?,
            final_normed: Rows::zeros(ctx, tokens)?,
            logits: Rows::zeros(ctx, tokens)?,
            argmax_partial_values: ctx
                .stream
                .alloc_zeros::<f32>(argmax_batch_bf16_split_partials_len(tokens, GLM52_VOCAB))?,
            argmax_partial_indices: ctx
                .stream
                .alloc_zeros::<i32>(argmax_batch_bf16_split_partials_len(tokens, GLM52_VOCAB))?,
            argmax_values: ctx.stream.alloc_zeros::<bf16>(tokens)?,
            argmax_indices: ctx.stream.alloc_zeros::<i32>(tokens)?,
        })
    }
}

