660	    pub(crate) fn build_fixed(
661	        ctx: &DeviceContext,
662	        w: &mut Glm52RankGpuWeights,
663	        max_model_len: usize,
664	        moe_topo: crate::Glm52MoeTopo,
665	        attn_shard: Option<usize>,
666	        drafter: &crate::Glm52Drafter,
667	        prefill_chunk_size: Option<usize>,
668	    ) -> Result<Glm52RankModelFixed> {
669	        ensure!(
670	            moe_topo.uses_tensor_replicated_moe() == attn_shard.is_some(),
671	            "GLM5.2 attention-TP shard must ride a tensor-replicated topology (topo {moe_topo:?}, \
672	             shard {attn_shard:?})"
673	        );
674	        ensure!(
675	            max_model_len > 0 && max_model_len.is_multiple_of(GLM52_MODEL_LEN_ALIGN),
676	            "GLM5.2 max_model_len {max_model_len} must be a positive multiple of \
677	             {GLM52_MODEL_LEN_ALIGN} (the FlashMLA page / index-K block size)"
678	        );
679	        let batch = GLM52_MAX_STEP_ROWS;
680	        let mla_heads = if attn_shard.is_some() {
681	            crate::config::GLM52_HEADS / moe_topo.device_count()
682	        } else {
683	            crate::config::GLM52_HEADS
684	        };
685	        let mla_backend = glm52_select_mla_backend(mla_heads)?;
686	        let mla_cache_bytes_per_token =
687	            glm52_persistent_mla_bytes_per_token(prefill_chunk_size.is_some(), mla_backend);
688	        let indexer_slices = (0..GLM52_LAYERS)
689	            .filter(|&layer| glm52_layer_has_full_indexer(layer))
690	            .count();
691	        log::info!(
692	            "GLM5.2 KV cache: topology={moe_topo:?} backend={mla_backend:?} page-first slab \
693	             page_tokens={} page_stride={GLM52_KV_PAGE_STRIDE} \
694	             page_content={GLM52_KV_PAGE_CONTENT_BYTES} mla_slices={} x {GLM52_KV_PAGE_MLA_BYTES} \
695	             index_k_slices={indexer_slices} x {GLM52_KV_PAGE_IDXK_BYTES} \
696	             (fp8[64,128]+f32[64]) + L78 mirrors",
697	            GLM52_FLASHMLA_SPARSE_PAGE_SIZE,
698	            GLM52_LAYERS,
699	        );
700	        log::info!(
701	            "GLM5.2 MLA execution: backend={:?} ({} heads/rank, persistent {} bytes/cache token)",
702	            mla_backend,
703	            mla_heads,
704	            mla_cache_bytes_per_token
705	        );
706	        let num_sm_parts = if attn_shard.is_some() {
707	            1
708	        } else {
709	            glm52_flashmla_sparse_decode_num_sm_parts()?
710	        };
711	        // The pool block count is decided by the measured launch fill AFTER
712	        // this build; the per-bucket sched/scratch below carry the count only
713	        // as launch metadata (nothing they allocate scales with it), so they
714	        // are built against a 1-block placeholder that `finish_kv` rebinds.
715	        // The layer offset stays 0 in the bucket-shared contract: one plan
716	        // serves all 78 layers, and the attend applies each layer's slab
717	        // offset per launch.
718	        let contract = Glm52FlashMlaSparseDecode {
719	            batch_size: batch,
720	            num_blocks: 1,
721	            kv_layer_offset_bytes: 0,
722	            kv_block_stride_bytes: GLM52_KV_PAGE_STRIDE,
723	            topk: GLM52_FLASHMLA_SPARSE_TOPK,
724	            num_sm_parts,
725	            sm_scale: GLM52_SM_SCALE,
726	        };
727	        let (table_width, index_cache_layout) = glm52_index_cache_layout(max_model_len, 1);
728	
729	        let mut layers = Vec::with_capacity(GLM52_LAYERS);
730	        for layer in 0..GLM52_LAYERS {
731	            layers.push(
732	                build::build_decoder_layer(ctx, w, layer, moe_topo, attn_shard)
733	                    .with_context(|| format!("build GLM5.2 decoder layer {layer}"))?,
734	            );
735	        }
736	        let mtp = drafter
737	            .is_mtp()
738	            .then(|| Glm52NativeMtp::build_fixed(ctx, w, max_model_len, moe_topo, attn_shard))
739	            .transpose()?;
740	
741	        let embed_raw = w.take_tensor("model.embed_tokens.weight")?;
742	        let lm_head_raw = w.take_tensor("lm_head.weight")?;
743	        ensure!(
744	            embed_raw.len() == GLM52_VOCAB * GLM52_HIDDEN * 2
745	                && lm_head_raw.len() == GLM52_VOCAB * GLM52_HIDDEN * 2,
746	            "GLM5.2 embed/lm_head byte lengths unexpected"
747	        );
748	        let embed = DeviceMatrix {
749	            data: retype_owned::<bf16>(&ctx.stream, embed_raw)?,
750	            rows: GLM52_VOCAB,
751	            cols: GLM52_HIDDEN,
752	        };
753	        let lm_head = DeviceMatrix {
754	            data: retype_owned::<bf16>(&ctx.stream, lm_head_raw)?,
755	            rows: GLM52_VOCAB,
756	            cols: GLM52_HIDDEN,
757	        };
758	        let (decode_lm_head, decode_vocab_start) = if let Some(rank) = attn_shard {
759	            let ranks = moe_topo.device_count();
760	            ensure!(
761	                rank < ranks && GLM52_VOCAB.is_multiple_of(ranks),
762	                "GLM5.2 vocab TP shard {rank}/{ranks} cannot partition {} rows",
763	                GLM52_VOCAB
764	            );
765	            let rows = GLM52_VOCAB / ranks;
766	            let start = rank * rows;
767	            let mut data = ctx.stream.alloc_zeros::<bf16>(rows * GLM52_HIDDEN)?;
768	            ctx.stream.memcpy_dtod(
769	                &lm_head
770	                    .data
771	                    .slice(start * GLM52_HIDDEN..(start + rows) * GLM52_HIDDEN),
772	                &mut data,
773	            )?;
774	            (
775	                Some(DeviceMatrix {
776	                    data,
777	                    rows,
778	                    cols: GLM52_HIDDEN,
779	                }),
780	                start,
781	            )
782	        } else {
783	            (None, 0)
