227	fn run_mla_oracle_gate(topk: usize, sm_parts_cap: Option<usize>) -> Result<()> {
228	    let model_path = std::env::var_os("PEGAINFER_TEST_MODEL_PATH")
229	        .map_or_else(|| PathBuf::from("models/GLM-5.2-FP8"), PathBuf::from);
230	
