232	    let digest = bf16_digest(&hidden_host);
233	    ensure!(
234	        digest == ORACLE_HIDDEN_DIGEST,
235	        "input digest {digest} != oracle {ORACLE_HIDDEN_DIGEST}: PRNG drift or stale probes — regenerate with tools/accuracy/glm52_oracle.py"
236	    );
