239	    let w = load_layer0(&ctx, &model_path)?;
240	
241	    let device_sm_parts = glm52_flashmla_sparse_decode_num_sm_parts()?;
242	    let contract = Glm52FlashMlaSparseDecode {
243	        batch_size: 1,
244	        num_blocks: ORACLE_CTX.div_ceil(GLM52_FLASHMLA_SPARSE_PAGE_SIZE),
245	        // Dedicated single-layer cache: tight page stride, no layer offset.
246	        kv_layer_offset_bytes: 0,
247	        kv_block_stride_bytes: crate::model::GLM52_KV_PAGE_MLA_BYTES,
248	        topk,
249	        num_sm_parts: sm_parts_cap.map_or(device_sm_parts, |cap| device_sm_parts.min(cap)),
250	        sm_scale: GLM52_SM_SCALE,
251	    };
252	    let mut cache = ctx
253	        .stream
254	        .alloc_zeros::<u8>(contract.packed_kv_cache_len())?;
255	    let mla_sched = Glm52MlaSchedMetadata::new(&ctx, contract, w.heads)?;
256	
257	    // Prefill via decode: position p writes its token into the cache, then
258	    // attends over the full prefix [0..=p] via a -1-padded top-k list.
259	    let mut outputs = Vec::with_capacity(ORACLE_CTX * HIDDEN);
260	    for position in 0..ORACLE_CTX {
261	        let mut hidden = crate::rows::Rows::<HIDDEN>::zeros(&ctx, 1)?;
262	        ctx.stream.memcpy_htod(
263	            &hidden_host[position * HIDDEN..(position + 1) * HIDDEN],
264	            hidden.data_mut(),
265	        )?;
266	        let (cos_host, sin_host) = rope_tables(position);
267	        let mut cos = ctx.stream.alloc_zeros::<bf16>(GLM52_ROPE_HALF)?;
268	        let mut sin = ctx.stream.alloc_zeros::<bf16>(GLM52_ROPE_HALF)?;
269	        ctx.stream.memcpy_htod(&cos_host, &mut cos)?;
270	        ctx.stream.memcpy_htod(&sin_host, &mut sin)?;
271	
272	        let mut topk_host = vec![-1i32; topk];
273	        for (slot, v) in topk_host.iter_mut().enumerate().take(position + 1) {
274	            *v = slot as i32;
275	        }
