277	        ctx.stream.memcpy_htod(&topk_host, &mut topk_dev)?;
278	
279	        let o = glm52_mla_decode_forward(
280	            &ctx, &w, &hidden, &cos, &sin, &mut cache, position, &topk_dev, &mla_sched,
